import {sha256} from './sha256.js';
const hash=async(id,password)=>sha256(id+':'+password);
const cidr=(ip,range)=>{if(range==='any'||range==='0.0.0.0/0')return true;const [net,p='32']=String(range).split('/');return validIPv4(ip)&&validIPv4(net)&&+p>=0&&+p<=32&&sameSubnet(ip,net,+p);};
const member=(user,groups)=>groups.includes('any')||!!user&&groups.some(g=>user.groups.includes(g)||user.id===g);
